// Logotipo Oficial H. Ayuntamiento de Coatzacoalcos 2026-2029 & Clinix Sistema de Salud Municipal
// Generado exactamente a partir de logo.png oficial

const LOGO_BASE64 = '';

function obtenerLogoHtml({ height = 48, maxWidth = 340, style = '' } = {}) {
  return `<img src="data:image/png;base64,${LOGO_BASE64}" style="height: ${height}px; max-width: ${maxWidth}px; object-fit: contain; ${style}" alt="Gobierno de Coatzacoalcos - Clinix Sistema de Salud Municipal">`;
}

function obtenerLogoCoatzacoalcosHtml(opts = {}) {
  return obtenerLogoHtml(opts);
}

module.exports = {
  obtenerLogoCoatzacoalcosHtml,
  LOGO_BASE64,
  obtenerLogoHtml
};
